"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["33860"],{96376(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.banca.integrantes_abaixo_do_minimo","status":422,"titulo":"A banca declara menos integrantes que o m\xednimo exigido"},"descricao":{"codigo":"uniplus.selecao.banca.integrantes_abaixo_do_minimo","requisitos":["UNI-REQ-0387","UNI-REQ-0276"],"oQueAconteceu":["A banca declara menos integrantes do que a publica\xe7\xe3o exige. O m\xednimo \xe9 o maior\\nvalor entre o qu\xf3rum da banca e o n\xfamero de corretores distintos que a regra de\\nconsolida\xe7\xe3o congelada de cada etapa julgada pela banca exige (UNI-REQ-0387). A\\nmensagem da recusa cita a banca, o local onde ela foi declarada (a fase ou a\\netapa), o n\xfamero de integrantes declarado e o m\xednimo exigido: por exemplo, a\\nbanca declara 2 integrantes, e o m\xednimo exigido \xe9 3.","O n\xfamero de corretores \xe9 par\xe2metro da regra de consolida\xe7\xe3o da etapa: a\\ncorre\xe7\xe3o independente declara 3, a avalia\xe7\xe3o \xfanica declara 1, e a etapa sem\\nconsolida\xe7\xe3o humana declara 0. Enquanto a regra de consolida\xe7\xe3o n\xe3o declara esse\\nn\xfamero, ele conta 0, e o m\xednimo \xe9 o pr\xf3prio qu\xf3rum da banca. A confer\xeancia l\xea s\xf3 esse n\xfamero, nunca o tipo da\\netapa nem o tipo do processo. Quem corrige e quem vota s\xe3o a mesma banca\\ndesignada, ent\xe3o uma banca curta demais nunca conseguiria corrigir o recurso\\ncom o terceiro corretor, e o problema s\xf3 apareceria no julgamento, com o prazo\\ncorrendo. Por isso a recusa vem na publica\xe7\xe3o.","Quais etapas a banca julga:","- a banca de an\xe1lise de recursos da etapa julga a pr\xf3pria etapa;\\n- a banca de an\xe1lise de recursos da fase julga a pr\xf3pria fase e as etapas dela\\n  que t\xeam recurso e n\xe3o t\xeam banca de recurso pr\xf3pria;\\n- a banca que julga mais de uma etapa usa o maior n\xfamero de corretores entre\\n  elas.","Exemplo: a banca de an\xe1lise de recursos de uma reda\xe7\xe3o com corre\xe7\xe3o\\nindependente declara 2 titulares e qu\xf3rum 2. O m\xednimo \xe9 3, o maior entre o\\nqu\xf3rum 2 e os 3 corretores, e a banca \xe9 recusada. Com 3 titulares e qu\xf3rum 2, \xe9\\naceita. Um qu\xf3rum maior que o n\xfamero de corretores \xe9 v\xe1lido: 5 integrantes e\\nqu\xf3rum 4, com 3 corretores, passa, porque o m\xednimo \xe9 4.","A confer\xeancia roda na publica\xe7\xe3o, na retifica\xe7\xe3o em ato \xfanico e no fechamento da\\nsess\xe3o de edi\xe7\xe3o. A recusa vem como o c\xf3digo desta p\xe1gina no corpo da resposta, e n\xe3o\\nna lista `errors[]`: a publica\xe7\xe3o aponta uma pend\xeancia por vez, a primeira que\\nencontra."],"comoResolver":["Aumente o n\xfamero de integrantes da banca at\xe9 o m\xednimo informado, ou, se o\\nedital permite, reduza o qu\xf3rum. Quando o m\xednimo vem do n\xfamero de corretores,\\nreduzir o qu\xf3rum n\xe3o basta: o n\xfamero de integrantes precisa alcan\xe7ar o n\xfamero\\nde corretores da etapa julgada.","A designa\xe7\xe3o de quem integra a banca confere depois o n\xfamero exato declarado\\n(UNI-REQ-0276), de modo que, garantido o m\xednimo na publica\xe7\xe3o, a opera\xe7\xe3o n\xe3o\\nfica sem corretores.","O painel de conformidade aponta a banca abaixo do m\xednimo antes da publica\xe7\xe3o, no\\nitem `cronograma_banca_com_o_minimo_de_integrantes`."],"ondeAparece":["Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Banca"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"fd5ea0ff72951399d2b2c1a4f29aeb3ea415db44"}}')}}]);